function abilityEditor(id){let x=findChar(id);form('Abilities & skill modifiers',[...Object.entries(x.abilities).map(([k,n])=>num(k,k.toUpperCase()+' score',n)),txt('proficiencies','Skill proficiencies (comma separated)',x.proficiencies.join(', ')),txt('saveProf','Saving throw proficiencies (str, dex, con, int, wis, cha)',x.saveProf.join(', ')),num('speed','Speed (feet)',x.speed),txt('overrides','Skill modifier overrides, one per line: Perception=5',Object.entries(x.skills).map(([k,n])=>k+'='+n).join('\n'),'textarea')],v=>{Object.keys(x.abilities).forEach(k=>x.abilities[k]=+v[k]);x.proficiencies=v.proficiencies.split(',').map(s=>s.trim()).filter(s=>s in E.skills);x.saveProf=v.saveProf.split(',').map(s=>s.trim().toLowerCase()).filter(s=>s in x.abilities);x.speed=+v.speed;x.skills={};v.overrides.split('\n').forEach(l=>{const [k,n]=l.split('=');if(k?.trim() in E.skills&&Number.isFinite(Number(n)))x.skills[k.trim()]=+n})})}
