const baseImportCharacter=importCharacter;importCharacter=async function(file,id){if(!file)return;try{toast('Reading character sheet locally…');let x=await api('/api/pdf',file,'application/pdf'),old=findChar(id);form(id?'Review character update':'Review imported character',[txt('name','Name — verify',x.name||old?.name||''),txt('class','Class — verify',x.class||old?.class||''),num('level','Level — verify',x.level),num('hp','Current HP — verify',x.hp),num('maxHp','Maximum HP — verify',x.maxHp),num('ac','Armor class — verify',x.ac),...Object.entries(x.abilities).map(([k,n])=>num(k,k.toUpperCase()+' score — verify',n)),txt('details','Extracted text (existing notes are kept on update)',x.details,'textarea')],v=>{let target=old||{id:uid()};for(const k of ['level','hp','maxHp','ac'])target[k]=+v[k];target.name=v.name||'Imported adventurer';target.class=v.class;target.abilities=Object.fromEntries(Object.keys(x.abilities).map(k=>[k,+v[k]]));target.skills={...(target.skills||{}),...x.skills};target.details=old?(old.details||'')+'\n\n— Updated PDF —\n'+v.details:v.details;E.normalizeCharacter(target);if(!old)C().characters.push(target);currentChar=target.id})}catch(e){toast(e.message)}};
function diceView(){return head('The dice tray','Three-dimensional dice, honest random results, and every roll remembered.',btn('Open floating tray','openDice()','gold'))+`<div class="card"><div class="tools">${[4,6,8,10,12,20,100].map(n=>btn('d'+n,`roll('1d${n}')`)).join('')}</div><div class="tools"><input id="diceExpression" value="2d6+3" aria-label="Dice expression">${btn('Roll',"roll($('#diceExpression').value)",'gold')}${btn('Advantage','advantage(true)')}${btn('Disadvantage','advantage(false)')}</div><label><input type="checkbox" ${state.settings.animation?'checked':''} onchange="state.settings.animation=this.checked;save()"> Animate dice</label> <label><input type="checkbox" ${state.settings.sound?'checked':''} onchange="state.settings.sound=this.checked;save()"> Dice sound</label><label> Dice colour <input style="width:70px" type="color" value="${state.settings.diceColor}" onchange="state.settings.diceColor=this.value;save()"></label></div><div class="card"><h2>Roll history</h2>${rollHistory()}</div>`}
function rollHistory(){return state.rolls.slice(0,30).map(r=>`<div class="row"><div><b>${esc(r.label||r.expr)}</b><div class="sub">${esc(r.expr)} · ${esc(r.detail)} · ${r.role==='player'?'Player':'DM'}</div></div><span class="stat">${r.total}</span></div>`).join('')||'<p>Roll your first die.</p>'}
