let lastVisual=null;function presentRoll(r){if(diceBusy){toast('Finish the current roll first');return}r.role=state.role;r.time=new Date().toISOString();r.detail=r.values.join(', ')+(r.modifier?' '+signed(r.modifier):'')+(r.keptIndex!==undefined?' · kept '+r.values[r.keptIndex]:'');state.rolls.unshift(r);state.rolls=state.rolls.slice(0,100);save();if(page==='Dice')render();openDice();lastVisual=r;diceBusy=true;$('#diceOutcome').innerHTML=`<span class="eyeline">${esc(r.label||r.expr)}</span><p>Rolling…</p>`;if(state.settings.sound)clatter();EmberDice3D.animate($('#diceCanvas'),r,state.settings.diceColor,()=>revealDice(r),!state.settings.animation||matchMedia('(prefers-reduced-motion: reduce)').matches)}
