function applyLastRoll(dmg){const id=$('#damageTarget').value;if(!id||!lastVisual||diceBusy){toast('Finish a roll and choose a target');return}if(!confirm(`Apply ${lastVisual.total} ${dmg?'damage':'healing'} to this target?`))return;changeCombatHp(id,dmg?Math.max(0,lastVisual.total):-Math.max(0,lastVisual.total));toast('Applied '+lastVisual.total+' '+(dmg?'damage':'healing'))}
let audioContext;function clatter(){try{audioContext||=new (window.AudioContext||window.webkitAudioContext)();for(let i=0;i<6;i++){const o=audioContext.createOscillator(),g=audioContext.createGain();o.type='triangle';o.frequency.value=180+i*43;g.gain.setValueAtTime(.03,audioContext.currentTime+i*.1);g.gain.exponentialRampToValueAtTime(.001,audioContext.currentTime+i*.1+.08);o.connect(g).connect(audioContext.destination);o.start(audioContext.currentTime+i*.1);o.stop(audioContext.currentTime+i*.1+.08)}}catch{}}
function encounterView(){const c=C();return head('Encounter workshop','Prepare opponents, run initiative, and apply rolls directly.',btn('＋ Combatant','combatant()','gold'))+`<div class="tools">${btn('Add party','addParty()')}${btn('Save encounter','saveEncounter()')}${btn('Next turn →','nextTurn()','gold')}${btn('Reset','resetCombat()')}</div><div class="card"><div class="cardhead"><div><span class="eyeline">ROUND ${c.round}</span><h2>${esc(c.combat[c.turn]?.name||'Prepare an encounter')}</h2></div><span>${c.combat.length} combatants</span></div>${combatRows()}</div><div class="grid two"><div class="card"><h2>Encounter plans</h2>${c.encounterPlans.map(p=>`<div class="row"><div><b>${esc(p.name)}</b><div class="sub">${p.creatures.length} creatures · ${esc(p.notes||'')}</div></div><div>${btn('Load',`loadEncounter('${p.id}')`)}${btn('Delete',`remove('encounterPlans','${p.id}')`)}</div></div>`).join('')||'<p>Build your roster above, then save it for another session.</p>'}</div><div class="card"><h2>Threat & loot notes</h2><p>Use the library to prepare reusable monster stat blocks and add them to the encounter. Difficulty depends on party resources and tactics; the app does not assign an automatic difficulty rating.</p>${btn('Open library',"go('Library')")}</div></div>`}
function combatRows(compact=false){return C().combat.map((x,i)=>`<div class="combatrow ${i===C().turn?'activeTurn':''}"><span class="stat">${x.initiative}</span><div><b>${esc(x.name)}</b><div class="sub">AC ${x.ac} · ${x.hp}/${x.maxHp??x.hp} HP${x.tempHp?' · '+x.tempHp+' temp':''}</div><div class="sub">${esc(x.condition||'No conditions')}${(x.effects||[]).map(e=>' · '+esc(e.name)+' ('+e.rounds+' rounds)').join('')}</div>${x.stats?`<details><summary>Stat block</summary><div class="note">${esc(x.stats)}</div></details>`:''}</div><div class="tools">${btn('Damage / heal',`combatDamage('${x.id}')`)}${btn('Effects',`condition('${x.id}')`)}${btn('Initiative',`initiativeEdit('${x.id}')`)}${btn('×',`remove('combat','${x.id}')`)}</div></div>`).join('')||'<p>Add party members and opponents to begin.</p>'}
function combatDamage(id){form('Damage / healing',[{...num('amount','Positive = damage · negative = healing',0),min:-99999}],v=>changeCombatHp(id,+v.amount))}
function changeCombatHp(id,amount){let x=C().combat.find(x=>x.id===id);if(!x)return;if(x.source&&findChar(x.source)){E.damage(findChar(x.source),amount);syncCombat(x.source)}else{if(x.maxHp===undefined)x.maxHp=x.hp;E.damage(x,amount)}save();render()}
combatHp=function(id,n){changeCombatHp(id,-n)};
addParty=function(){C().characters.forEach(x=>{if(!C().combat.some(c=>c.source===x.id))C().combat.push({id:uid(),source:x.id,name:x.name,hp:x.hp,maxHp:x.maxHp,tempHp:x.tempHp,ac:x.ac,initiative:random(20)+E.mod(x.abilities.dex),condition:x.conditions.join(', '),effects:[]})});C().combat.sort((a,b)=>b.initiative-a.initiative);C().turn=0;save();render()};
function initiativeEdit(id){const x=C().combat.find(x=>x.id===id);form('Initiative',[{...num('initiative','Initiative',x.initiative),min:-99}],v=>{x.initiative=+v.initiative;C().combat.sort((a,b)=>b.initiative-a.initiative);C().turn=0})}
condition=function(id){let x=C().combat.find(x=>x.id===id);form('Conditions & timed effects',[txt('condition','Conditions (comma separated)',x.condition),txt('effects','Timed effects, one per line: Bless | 3',x.effects?.map(e=>e.name+' | '+e.rounds).join('\n')||'','textarea')],v=>{x.condition=v.condition;x.effects=v.effects.split('\n').map(l=>{const [name,n]=l.split('|');return{name:name.trim(),rounds:Math.max(0,parseInt(n)||0)}}).filter(e=>e.name);if(x.source&&findChar(x.source)){findChar(x.source).conditions=v.condition.split(',').map(s=>s.trim()).filter(Boolean)}})};
nextTurn=function(){const c=C();if(!c.combat.length)return;if(++c.turn>=c.combat.length){c.turn=0;c.round++;c.combat.forEach(x=>{x.effects=(x.effects||[]).map(e=>({...e,rounds:e.rounds-1})).filter(e=>e.rounds>0)})}save();render();const active=c.combat[c.turn];if(active.effects?.length)toast(active.effects.map(e=>e.name+' ('+e.rounds+' rounds)').join(', '))};
function saveEncounter(){form('Save encounter',[txt('name','Encounter name'),txt('notes','Loot, tactics & other notes','','textarea')],v=>C().encounterPlans.push({id:uid(),...v,creatures:C().combat.filter(x=>!x.source).map(x=>({...x,hp:x.maxHp??x.hp}))}))}
function loadEncounter(id){if(C().combat.length&&!confirm('Replace the current encounter roster?'))return;let p=C().encounterPlans.find(p=>p.id===id);C().combat=p.creatures.map(x=>({...structuredClone(x),id:uid(),initiative:random(20)}));C().turn=0;C().round=1;save();render()}
let mapLayers={terrain:true,drawings:true,tokens:true};const activeMap=()=>C().maps.find(m=>m.id===C().activeMap)||C().maps[0];
function mapView(){let m=activeMap();return head('The cartographer’s workbench','Terrain, rooms, drawing layers, tokens and fog of war.',btn('＋ Map','mapEditor()','gold'))+`<div class="tools"><select style="max-width:280px" aria-label="Active map" onchange="C().activeMap=this.value;selectedToken=null;save();render()">${C().maps.map(x=>`<option value="${x.id}" ${x.id===m.id?'selected':''}>${esc(x.name)}${x.template?' · template':''}</option>`).join('')}</select>${btn('Map details',`mapEditor('${m.id}')`)}${btn('Duplicate / template','duplicateMap()')}${btn('Import image',"picker('image/png,image/jpeg,image/webp',importMapImage)")}${btn('Player display','openPlayerDisplay()')}${btn('Export PNG','exportMapV2()')}</div><div class="maplayout"><section><div class="card mapcard"><div class="tools">${[['terrain','Paint'],['room','Room'],['draw','Draw'],['erase','Erase drawing'],['token','Move tokens'],['reveal','Reveal fog'],['hide','Hide fog'],['measure','Measure']].map(([t,n])=>btn(n,`setMapTool('${t}')`,mapTool===t?'gold':'')).join('')}</div><div class="tools"><label>Terrain <select onchange="terrain=+this.value">${['Floor / transparent','Stone','Forest','Water','Void','Path'].map((t,i)=>`<option value="${i}" ${i===terrain?'selected':''}>${t}</option>`).join('')}</select></label><label>Ink <input type="color" value="${drawColor}" onchange="drawColor=this.value"></label><label>Zoom <input style="width:110px" type="range" min="0.5" max="2.5" step="0.1" value="${mapZoom}" oninput="mapZoom=+this.value;resizeMapCanvas()"></label><label><input type="checkbox" ${m.grid?'checked':''} onchange="activeMap().grid=this.checked;save();redrawMap()"> Grid</label>${btn('Cover all','fogAll(true)')}${btn('Reveal all','fogAll(false)')}</div><div class="mapscroll"><canvas id="battlemap" aria-label="Interactive battle map"></canvas></div><div class="tools">${Object.keys(mapLayers).map(k=>`<label><input type="checkbox" ${mapLayers[k]?'checked':''} onchange="mapLayers['${k}']=this.checked;redrawMap()"> ${k}</label>`).join('')}</div><p class="small">${m.w} × ${m.h} squares · ${m.feet} ft per square. Drag to paint or move tokens. Room draws a filled rectangle. Measurement uses one square per diagonal. Hold the scroll bars to pan a zoomed map.</p></div></section><section><div class="card"><div class="cardhead"><h2>Tokens</h2>${btn('＋ Token','tokenEditor()')}</div>${m.tokens.map(t=>`<div class="row"><div><span class="tokenDot" style="background:${/^#[a-f0-9]{6}$/i.test(t.color)?t.color:'#dbb576'}"></span><b>${esc(t.name)}</b><div class="sub">${t.hidden?'DM only':'Visible'} · ${t.x+1}, ${t.y+1}</div></div><div>${btn('Edit',`tokenEditor('${t.id}')`)}${btn('×',`deleteToken('${t.id}')`)}</div></div>`).join('')||'<p>Add heroes and enemies, then drag their tokens on the map.</p>'}</div><div class="card"><h2>Map notes</h2><div class="note">${esc(m.notes)}</div>${btn('Edit notes',`mapEditor('${m.id}')`)}<div class="tools">${btn('Remove map','deleteMap()')}</div></div></section></div>`}
function setMapTool(t){mapTool=t;measureStart=measureEnd=null;render()}
function mapEditor(id){let m=C().maps.find(m=>m.id===id);form(id?'Map details':'New battle map',[txt('name','Map name',m?.name||''),{...num('w','Width in squares (8–60)',m?.w||24),min:8,max:60},{...num('h','Height in squares (8–60)',m?.h||24),min:8,max:60},{...num('feet','Feet per square',m?.feet||5),min:1,max:100},txt('notes','DM notes',m?.notes||'','textarea')],v=>{let w=+v.w,h=+v.h;if(!m){m=E.map(uid(),v.name,w,h);C().maps.push(m)}else if(w!==m.w||h!==m.h){let cells=Array(w*h).fill(0),fog=Array(w*h).fill(false);for(let y=0;y<Math.min(h,m.h);y++)for(let x=0;x<Math.min(w,m.w);x++){cells[y*w+x]=m.cells[y*m.w+x];fog[y*w+x]=m.fog[y*m.w+x]}m.cells=cells;m.fog=fog;m.tokens=m.tokens.filter(t=>t.x<w&&t.y<h);m.w=w;m.h=h}Object.assign(m,{name:v.name,feet:+v.feet,notes:v.notes});C().activeMap=m.id})}
function duplicateMap(){let m=activeMap();form('Duplicate / save as template',[txt('name','Name',m.name+' copy'),{key:'template',label:'Type',options:['Battle map','Reusable template']}],v=>{let n=structuredClone(m);n.id=uid();n.name=v.name;n.template=v.template==='Reusable template';n.tokens=n.tokens.map(t=>({...t,id:uid()}));C().maps.push(n);C().activeMap=n.id})}
async function importMapImage(f){const m=activeMap();let a=await asset(f);m.image=a.url;save();render();toast('Background imported. Floor cells show the image beneath.')}
function fogAll(hidden){activeMap().fog.fill(hidden);save();redrawMap()}
function tokenEditor(id){let m=activeMap(),t=m.tokens.find(t=>t.id===id)||{};form('Map token',[txt('name','Token name',t.name),txt('color','Colour (#rrggbb)',t.color||'#dbb576'),{key:'hidden',label:'Visibility',options:['Visible to players','DM only'],value:t.hidden?'DM only':'Visible to players'},{...num('x','Column (1–'+m.w+')',(t.x??Math.floor(m.w/2))+1),min:1,max:m.w},{...num('y','Row (1–'+m.h+')',(t.y??Math.floor(m.h/2))+1),min:1,max:m.h}],v=>{let a={name:v.name,color:/^#[a-f0-9]{6}$/i.test(v.color)?v.color:'#dbb576',hidden:v.hidden==='DM only',x:+v.x-1,y:+v.y-1};if(id)Object.assign(t,a);else m.tokens.push({id:uid(),...a});mapTool='token'})}
function deleteToken(id){activeMap().tokens=activeMap().tokens.filter(t=>t.id!==id);save();render()}
function deleteMap(){if(C().maps.length<=1){toast('Keep at least one map per campaign');return}if(!confirm('Delete this map? Undo is available.'))return;C().maps=C().maps.filter(m=>m.id!==activeMap().id);C().activeMap=C().maps[0].id;save();render()}
function resizeMapCanvas(){const can=$('#battlemap');if(can){can.style.width=(activeMap().w*32*mapZoom)+'px';can.style.maxWidth='none'}}
function redrawMap(){const can=$('#battlemap');if(can)EmberMap.draw(can,activeMap(),{selected:selectedToken,measure:[measureStart,measureEnd],layers:mapLayers,redraw:redrawMap})}
function bindMap(){const can=$('#battlemap');if(!can)return;resizeMapCanvas();redrawMap();let down=false,start=null,moved=false;const loc=e=>{let r=can.getBoundingClientRect();return{x:Math.min(activeMap().w-1,Math.max(0,Math.floor((e.clientX-r.left)/r.width*activeMap().w))),y:Math.min(activeMap().h-1,Math.max(0,Math.floor((e.clientY-r.top)/r.height*activeMap().h))),fx:(e.clientX-r.left)/r.width*activeMap().w,fy:(e.clientY-r.top)/r.height*activeMap().h}};
const paintAt=p=>{let m=activeMap(),i=p.y*m.w+p.x;if(mapTool==='terrain')m.cells[i]=terrain;else if(mapTool==='reveal'||mapTool==='hide')m.fog[i]=mapTool==='hide';else if(mapTool==='token'&&selectedToken){let t=m.tokens.find(t=>t.id===selectedToken);if(t){t.x=p.x;t.y=p.y}}else if(mapTool==='draw'&&drawing)drawing.points.push([p.fx,p.fy]);else if(mapTool==='erase')m.marks=m.marks.filter(mark=>!mark.points.some(([x,y])=>Math.hypot(x-p.fx,y-p.fy)<.8));else if(mapTool==='measure')measureEnd={x:p.x,y:p.y};redrawMap()};
can.onpointerdown=e=>{if(e.button!==0)return;down=true;moved=false;can.setPointerCapture(e.pointerId);let p=loc(e);start=p;if(mapTool==='token')selectedToken=[...activeMap().tokens].reverse().find(t=>t.x===p.x&&t.y===p.y)?.id||null;if(mapTool==='draw'){drawing={id:uid(),color:drawColor,width:3,points:[[p.fx,p.fy]]};activeMap().marks.push(drawing)}if(mapTool==='measure')measureStart={x:p.x,y:p.y};paintAt(p)};
can.onpointermove=e=>{if(down){moved=true;paintAt(loc(e))}};
can.onpointerup=e=>{if(!down)return;down=false;let end=loc(e);if(mapTool==='room'){const m=activeMap();for(let y=Math.min(start.y,end.y);y<=Math.max(start.y,end.y);y++)for(let x=Math.min(start.x,end.x);x<=Math.max(start.x,end.x);x++)m.cells[y*m.w+x]=terrain}drawing=null;if(mapTool!=='measure')save();redrawMap()};can.onpointercancel=()=>{down=false;drawing=null;save()};}
function exportMapV2(){const m=activeMap(),can=document.createElement('canvas');EmberMap.draw(can,m,{player:true,redraw:()=>{}});can.toBlob(blob=>downloadBlob(blob,(m.name.replace(/[^a-z0-9-]/gi,'_')||'map')+'.png'))}
function downloadBlob(blob,name){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),10000)}
async function openPlayerDisplay(){await saveQueue;if(window.pywebview?.api?.open_display)await window.pywebview.api.open_display();else window.open('/display.html','ember-player-display','width=1200,height=850')}
function wikiView(){let pages=C().wiki.filter(p=>state.role==='dm'||!p.secret);return head('Your living campaign wiki','Connect entries with [[Page title]]. Links work in journals, NPC notes and session plans.',btn('＋ Page','wikiEditor()','gold'))+`<input placeholder="Search people, places, factions and lore…" aria-label="Search wiki" value="${esc(filterWiki)}" oninput="filterWiki=this.value;filterCards(this.value)"><div class="grid" style="margin-top:20px">${pages.map(p=>`<article class="card searchable"><div class="cardhead"><span class="badge">${esc(p.type)}${p.secret?' · DM ONLY':''}</span>${btn('Edit',`wikiEditor('${p.id}')`)}</div><h3>${esc(p.title)}</h3><div class="note">${esc(p.body)}</div><p class="small">Linked from: ${wikiBacklinks(p.title)}</p><div class="tools">${btn('Attachments',`attachmentPicker('${p.id}')`)}${btn('Delete',`remove('wiki','${p.id}')`)}</div>${(p.attachments||[]).map(a=>`<a class="assetlink" href="${safeAsset(a.url)}" download>${esc(a.name)}</a>`).join('')}</article>`).join('')||'<div class="card empty">Add a location, faction, person, secret or piece of lore.</div>'}</div>`}
function wikiBacklinks(title){let sources=[...C().wiki.filter(p=>state.role==='dm'||!p.secret),...C().notes,...C().npcs,...C().sessions,...C().quests];return sources.filter(p=>p.body?.toLowerCase().includes('[['+title.toLowerCase()+']]')).map(p=>esc(p.title)).join(', ')||'No backlinks yet'}
function wikiEditor(id,title=''){let p=C().wiki.find(p=>p.id===id)||{};form('Wiki page',[txt('title','Page title',p.title||title),{key:'type',label:'Type',options:['Location','Person','Faction','Lore','Quest','Other'],value:p.type||'Location'},{key:'secret',label:'Visibility',options:['Shared','DM only'],value:p.secret?'DM only':'Shared'},txt('body','Page text — link with [[Title]]',p.body,'textarea')],v=>{v.secret=v.secret==='DM only';if(id)Object.assign(p,v);else C().wiki.push({id:uid(),...v})})}
function openWikiTitle(title){const p=C().wiki.find(p=>p.title.toLowerCase()===title.toLowerCase()&&(state.role==='dm'||!p.secret));if(p){page='Wiki';render();const cards=[...document.querySelectorAll('.searchable')];cards.find(el=>el.querySelector('h3')?.textContent===p.title)?.scrollIntoView({behavior:'smooth',block:'center'})}else wikiEditor(undefined,title)}
async function attachmentPicker(id){picker('image/png,image/jpeg,image/webp,.pdf',async f=>{const p=C().wiki.find(p=>p.id===id),a=await asset(f);p.attachments||=[];p.attachments.push({name:f.name,url:a.url});save();render()})}
function timelineView(){const c=C(),cal=c.calendar;return head('A world that keeps moving','Track campaign days, weather, travel and events.',btn('＋ Event','eventEditor()','gold'))+`<div class="card"><div class="cardhead"><div><span class="eyeline">CAMPAIGN CLOCK</span><h2>Day ${cal.day} · ${esc(cal.month)}, year ${cal.year}</h2><p>${esc(cal.weather)}${cal.travel?' · '+esc(cal.travel):''}</p></div><div>${btn('Advance day','advanceDays(1)')}${btn('Set calendar','calendarEditor()')}${btn('Weather','randomWeather()')}${btn('Log travel','travelEditor()')}</div></div><p class="small">The campaign day is a continuous counter. Month and year labels are yours to set for any homebrew calendar.</p></div><div class="card">${[...c.timeline].sort((a,b)=>a.day-b.day).map(e=>`<div class="row"><div><span class="badge">DAY ${e.day}${e.day<=cal.day&&!e.done?' · DUE':''}</span><h3>${esc(e.title)}</h3><div class="note">${esc(e.body)}</div></div><div>${btn(e.done?'Reopen':'Complete',`toggleEvent('${e.id}')`)}${btn('Edit',`eventEditor('${e.id}')`)}${btn('×',`remove('timeline','${e.id}')`)}</div></div>`).join('')||'<p>Add planned events and record what happened during the adventure.</p>'}</div>`}
function eventEditor(id){let e=C().timeline.find(e=>e.id===id)||{};form('Timeline event',[txt('title','Event title',e.title),num('day','Campaign day',e.day||C().calendar.day),txt('body','Details',e.body,'textarea')],v=>{v.day=+v.day;if(id)Object.assign(e,v);else C().timeline.push({id:uid(),done:false,...v})})}
function advanceDays(n){C().calendar.day=Math.max(1,C().calendar.day+n);save();render()}
function calendarEditor(){let c=C().calendar;form('Campaign calendar',[num('day','Continuous campaign day',c.day),txt('month','Month / season label',c.month),num('year','Year',c.year),txt('weather','Weather',c.weather),txt('travel','Current location / travel',c.travel)],v=>{v.day=Math.max(1,+v.day);v.year=+v.year;Object.assign(c,v)})}
function randomWeather(){const weather=['Clear skies','Light rain','Heavy rain','Cold winds','Morning fog','Thunderstorm','Warm and dry','Overcast'];C().calendar.weather=weather[random(weather.length)-1];save();render()}
function toggleEvent(id){let e=C().timeline.find(e=>e.id===id);e.done=!e.done;save();render()}
function travelEditor(){form('Travel log',[txt('title','Route / destination'),num('days','Days travelled',1),num('miles','Distance in miles',24),txt('notes','Encounters & discoveries','','textarea')],v=>{C().timeline.push({id:uid(),title:'Travel: '+v.title,day:C().calendar.day,body:v.miles+' miles over '+v.days+' days.\n'+v.notes,done:true});C().calendar.day+=+v.days;C().calendar.travel=v.title})}
let inventoryOwner='Party';function inventoryView(){const c=C(),owners=[['Party','Party treasure'],...c.characters.map(x=>[x.id,x.name])];if(!owners.some(o=>o[0]===inventoryOwner))inventoryOwner='Party';let items=c.items.filter(x=>(x.owner||'Party')===inventoryOwner),weight=items.reduce((s,x)=>s+(x.quantity??1)*(x.weight||0),0),wallet=inventoryOwner==='Party'?c.coins:findChar(inventoryOwner).currency;return head('Equipment & treasure','Quantities, weight, containers, currency and ownership.',btn('＋ Item','itemEditor()','gold'))+`<div class="tools"><select aria-label="Inventory owner" style="max-width:280px" onchange="inventoryOwner=this.value;render()">${owners.map(([id,n])=>`<option value="${id}" ${id===inventoryOwner?'selected':''}>${esc(n)}</option>`).join('')}</select><span class="badge">${weight.toFixed(2)} LB TOTAL</span>${btn('Edit currency','currencyEditor()')}</div><div class="card wallet">${Object.entries(wallet).map(([k,n])=>`<div><span class="stat">${n}</span><small>${k.toUpperCase()}</small></div>`).join('')}</div><div class="card">${table(items.map(x=>`<tr><td><b>${esc(x.title)}</b><div class="sub">${esc(x.body)}</div></td><td>${x.quantity??1}</td><td>${x.weight||0} lb</td><td>${esc(c.items.find(p=>p.id===x.container)?.title||'—')}</td><td>${x.equipped?'Equipped ':''}${x.attuned?'Attuned':''}</td><td>${btn('−',`itemQuantity('${x.id}',-1)`)}${btn('+',`itemQuantity('${x.id}',1)`)}${btn('Edit',`itemEditor('${x.id}')`)}${btn('×',`remove('items','${x.id}')`)}</td></tr>`),['Item','Qty','Unit weight','Container','Status','Actions'])}<p class="small">Container contents count toward carried weight. Encumbrance limits and attunement restrictions are reviewed manually.</p></div>`}
function itemQuantity(id,d){let x=C().items.find(x=>x.id===id);x.quantity=Math.max(0,(x.quantity??1)+d);save();render()}
function itemEditor(id){const x=C().items.find(x=>x.id===id)||{};let candidates=C().items.filter(i=>i.id!==id&&!isContainerDescendant(i.id,id));form('Inventory item',[txt('title','Item name',x.title),num('quantity','Quantity',x.quantity??1),{...num('weight','Weight per item (lb)',x.weight||0),step:.01},txt('body','Description',x.body,'textarea'),{key:'owner',label:'Owner',options:['Party',...C().characters.map(c=>c.name)],value:'Party'},{key:'container',label:'Container',options:['None',...candidates.map(i=>i.title)]},{key:'equipped',label:'Equipment',options:['Carried','Equipped'],value:x.equipped?'Equipped':'Carried'},{key:'attuned',label:'Attunement',options:['Not attuned','Attuned'],value:x.attuned?'Attuned':'Not attuned'}],v=>{v.quantity=+v.quantity;v.weight=+v.weight;v.equipped=v.equipped==='Equipped';v.attuned=v.attuned==='Attuned';if(id)Object.assign(x,v);else C().items.push({id:uid(),...v})});$('#f-owner').innerHTML=`<option value="Party">Party treasure</option>`+C().characters.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('');$('#f-owner').value=x.owner||inventoryOwner;$('#f-container').innerHTML='<option value="">None</option>'+candidates.map(i=>`<option value="${i.id}">${esc(i.title)}</option>`).join('');$('#f-container').value=x.container||''}
function isContainerDescendant(itemId,parentId){if(!parentId)return false;const seen=new Set();let x=C().items.find(x=>x.id===itemId);while(x?.container&&!seen.has(x.id)){if(x.container===parentId)return true;seen.add(x.id);x=C().items.find(i=>i.id===x.container)}return false}
function currencyEditor(){let wallet=inventoryOwner==='Party'?C().coins:findChar(inventoryOwner).currency;form('Currency',Object.entries(wallet).map(([k,n])=>num(k,k.toUpperCase(),n)),v=>Object.keys(wallet).forEach(k=>wallet[k]=+v[k]))}
const libraryTypes=['Monster','Spell','Item','Condition','Rule','Homebrew'];function libraryView(){return head('Your offline reference library','Search your own rules, monsters, spells, items and homebrew.',btn('＋ Entry','libraryEditor()','gold'))+`<div class="tools"><input aria-label="Search library" placeholder="Search your reference library…" oninput="filterCards(this.value)">${btn('Import JSON',"picker('.json',importLibrary)")}${btn('Export JSON','exportLibrary()')}${btn('Attach reference PDF',"picker('.pdf',attachLibraryPDF)")}${btn('Add sample stat block','sampleMonster()')}</div><p class="small">This library stores your own material. Commercial rulebooks and a complete official rules database are not bundled.</p><div class="grid">${C().library.map(l=>`<div class="card searchable"><div class="cardhead"><span class="badge">${esc(l.type)}</span>${btn('Edit',`libraryEditor('${l.id}')`)}</div><h3>${esc(l.title)}</h3><div class="note">${esc(l.body)}</div>${l.attachment?`<a class="assetlink" href="${safeAsset(l.attachment)}" download>Open reference PDF</a>`:''}<div class="tools">${l.type==='Monster'?btn('Add to encounter',`monsterToCombat('${l.id}')`):''}${btn('Delete',`remove('library','${l.id}')`)}</div></div>`).join('')||'<div class="card empty">Add a rule, spell or homebrew monster. Import your own JSON collection or attach a local reference PDF.</div>'}</div>`}
function libraryEditor(id){let l=C().library.find(l=>l.id===id)||{};form('Reference entry',[txt('title','Title',l.title),{key:'type',label:'Category',options:libraryTypes,value:l.type||'Rule'},num('hp','HP (monsters)',l.hp||10),num('ac','AC (monsters)',l.ac||10),txt('body','Rules / stat block / description',l.body,'textarea')],v=>{v.hp=+v.hp;v.ac=+v.ac;if(id)Object.assign(l,v);else C().library.push({id:uid(),...v})})}
function monsterToCombat(id){let l=C().library.find(l=>l.id===id);form('Add monster group',[{...num('count','How many? (1–30)',1),min:1,max:30}],v=>{for(let i=0;i<+v.count;i++)C().combat.push({id:uid(),name:l.title+(+v.count>1?' '+(i+1):''),hp:l.hp||10,maxHp:l.hp||10,ac:l.ac||10,initiative:random(20),stats:l.body,condition:'',effects:[]});C().combat.sort((a,b)=>b.initiative-a.initiative);page='Encounters'})}
function exportLibrary(){download(JSON.stringify(C().library,null,2),'Ember-Library.json')}
async function importLibrary(f){let entries=JSON.parse(await f.text());if(!Array.isArray(entries)||entries.length>10000||!entries.every(x=>typeof x.title==='string'&&typeof x.body==='string'))throw Error('Expected an array of entries with title, body and type.');C().library.push(...entries.map(x=>({id:uid(),title:x.title,body:x.body,type:libraryTypes.includes(x.type)?x.type:'Homebrew',hp:Math.max(1,Number(x.hp)||10),ac:Math.max(1,Number(x.ac)||10)})));save();render();toast('Reference entries imported')}
async function attachLibraryPDF(f){let a=await asset(f);C().library.push({id:uid(),title:f.name,type:'Rule',body:'Local reference PDF. Search uses the title and your editable notes.',attachment:a.url});save();render()}
function sampleMonster(){C().library.push({id:uid(),type:'Monster',title:'Briar Sentinel (homebrew example)',hp:22,ac:13,body:'Medium plant · Speed 25 ft\nSTR 14 DEX 10 CON 14 INT 5 WIS 12 CHA 5\nThorn lash: +4 to hit, reach 10 ft, 1d6+2 piercing.\nRooted watch: notices creatures moving through its grove.\nLoot idea: a living seed.\nOriginal sample for editing; balance for your party.'});save();render()}
const soundPlayers=new Map();function audioView(){return head('Set the scene','Local music, ambience and sound effects that keep playing as you work.',btn('＋ Import audio',"picker('.mp3,.wav,.ogg,.m4a',importAudio)",'gold'))+`<div class="tools">${btn('Stop all audio','stopAllAudio()')}</div><div class="grid">${C().audio.map(t=>`<div class="card"><span class="badge">${esc(t.kind)}</span><h3>${esc(t.name)}</h3><div class="tools">${btn(soundPlayers.get(t.id)?.paused===false?'Pause':'Play',`toggleAudio('${t.id}')`)}${btn('Stop',`stopAudio('${t.id}')`)}${btn('Edit',`audioEditor('${t.id}')`)}${btn('Delete',`deleteAudio('${t.id}')`)}</div><label>Volume <input type="range" min="0" max="1" step=".05" value="${t.volume??.5}" oninput="audioVolume('${t.id}',+this.value)"></label><label><input type="checkbox" ${t.loop?'checked':''} onchange="audioLoop('${t.id}',this.checked)"> Loop</label></div>`).join('')||'<div class="card empty">Import music or ambience you own. No streaming or internet connection is needed.</div>'}</div>`}
async function importAudio(f){const a=await asset(f);C().audio.push({id:uid(),name:f.name,url:a.url,kind:'Music',volume:.5,loop:true});save();render()}
function audioEditor(id){const t=C().audio.find(t=>t.id===id);form('Audio track',[txt('name','Name',t.name),{key:'kind',label:'Type',options:['Music','Ambience','Sound effect'],value:t.kind}],v=>Object.assign(t,v))}
async function toggleAudio(id){const t=C().audio.find(t=>t.id===id);let p=soundPlayers.get(id);if(!p){p=new Audio(safeAsset(t.url));p.loop=t.loop;p.volume=t.volume??.5;soundPlayers.set(id,p)}try{if(p.paused)await p.play();else p.pause();render()}catch{toast('This audio format could not play. Try MP3 or WAV.')}}
function stopAudio(id){const p=soundPlayers.get(id);if(p){p.pause();p.currentTime=0}render()}
function stopAllAudio(){soundPlayers.forEach(p=>{p.pause();p.currentTime=0});if(page==='Audio')render()}
function audioVolume(id,n){C().audio.find(t=>t.id===id).volume=n;const p=soundPlayers.get(id);if(p)p.volume=n;save()}
function audioLoop(id,on){C().audio.find(t=>t.id===id).loop=on;const p=soundPlayers.get(id);if(p)p.loop=on;save()}
function deleteAudio(id){stopAudio(id);soundPlayers.delete(id);remove('audio',id)}
function sessionView(){const c=C(),x=findChar()||c.characters[0];return head(state.role==='dm'?'Behind the screen':'At the table','Map, character, initiative and notes in one workspace.',btn('Open dice tray','openDice()','gold'))+`<div class="tools">${btn('Player display','openPlayerDisplay()')}${btn('Quick note','openNote()')}${state.role==='dm'?btn('Next turn','nextTurn()'):''}${btn('Audio',"go('Audio')")}</div><div class="sessiongrid"><div><div class="card"><div class="cardhead"><h2>${esc(activeMap().name)}</h2>${btn('Map editor',"go('Maps')")}</div><div class="mapscroll"><canvas id="battlemap" aria-label="Session battle map"></canvas></div><p class="small">${state.role==='dm'?'Use the map editor for fog and token tools.':'Player view shows revealed terrain and visible tokens.'}</p></div><div class="card"><h2>${state.role==='dm'?'Initiative · round '+c.round:'Quest journal'}</h2>${state.role==='dm'?combatRows(true):c.quests.filter(q=>q.status!=='Completed').map(q=>`<h3>${esc(q.title)}</h3><div class="note">${esc(q.body)}</div>`).join('')}</div></div><div><div class="card"><h2>Party at a glance</h2>${c.characters.map(ch=>`<div class="row"><div><b>${esc(ch.name)}</b><div class="sub">${ch.hp}/${ch.maxHp} HP · AC ${ch.ac} · ${esc(ch.conditions.join(', '))}</div></div><div>${btn('Sheet',`currentChar='${ch.id}';go('Characters')`)}${btn('HP',`hpDialog('${ch.id}')`)}</div></div>`).join('')||'<p>Add characters to your party.</p>'}</div>${x?`<div class="card"><h2>${esc(x.name)} · quick actions</h2><div class="tools">${Object.keys(x.abilities).map(a=>btn(a.toUpperCase()+' '+signed(E.mod(x.abilities[a])),`rollCheck('${x.id}','${a}',false)`)).join('')}${x.actions.map(a=>btn(esc(a.name),`actionRoll('${x.id}','${a.id}',false)`)).join('')}</div></div>`:''}<div class="card"><h2>Session scratchpad</h2><textarea id="scratchpad" aria-label="Session scratchpad" oninput="C().scratchpad=this.value;queueScratchSave()">${esc(c.scratchpad||'')}</textarea><p class="small">Saves after a short pause. Use [[Page title]] to reference your wiki.</p>${btn('Save as journal note','scratchToJournal()')}</div><div class="card"><h2>Upcoming events</h2>${c.timeline.filter(e=>!e.done).sort((a,b)=>a.day-b.day).slice(0,4).map(e=>`<div class="row"><span>Day ${e.day} · ${esc(e.title)}</span></div>`).join('')||'<p>Your calendar is clear.</p>'}</div></div></div>`}
const originalBindMap=bindMap;bindMap=function(){if(page==='Session'&&state.role==='player'){const can=$('#battlemap');if(can){can.style.width='100%';EmberMap.draw(can,activeMap(),{player:true,redraw:()=>bindMap()})}return}if(page==='Session'){mapTool='token';originalBindMap();return}originalBindMap()};
let scratchTimer;function queueScratchSave(){window.__scratchPending=true;clearTimeout(scratchTimer);scratchTimer=setTimeout(()=>{window.__scratchPending=false;save()},450)}function scratchToJournal(){C().notes.unshift({id:uid(),title:'Session notes · day '+C().calendar.day,body:C().scratchpad||'',tag:'Session'});save();toast('Copied to journal')}
function backupsView(){return head('Keep your story safe','Undo recent edits, restore an autosave or move everything to another PC.')+`<div class="grid two"><div class="card"><h2>Portable workspace</h2><p>Export campaigns with maps, images, reference PDFs, and audio files. Keep a copy on another drive.</p><div class="tools">${btn('Export everything (.zip)','backup()','gold')}${btn('Restore ZIP / JSON',"picker('.zip,.json',restorePortable)")}${btn('Export JSON only','jsonBackup()')}</div><p class="small">ZIP restores include assets. Old JSON exports are supported but do not contain attachments. Import limit: 250 MB compressed, 500 MB expanded.</p></div><div class="card"><h2>Undo & redo</h2><p>Up to 25 recent workspace changes are available during this app session.</p><div class="tools">${btn('Undo','undo()')}${btn('Redo','redo()')}</div><p class="small">Ctrl+Z / Ctrl+Shift+Z work outside text fields. Automatic disk backups survive app restarts.</p></div></div><div class="card"><h2>Automatic backups</h2><p>The 30 most recent saved revisions are kept on your PC. Restore replaces the entire workspace; current files are backed up first.</p><div id="backupList">Loading backups…</div></div>`}
backup=async function(){try{if(window.__loadFailed)throw Error('Restore a valid backup before exporting.');await saveQueue;const r=await fetch('/api/export');if(!r.ok)throw Error((await r.json()).error);downloadBlob(await r.blob(),'Ember-Table-Campaigns.zip');toast('Portable export created')}catch(e){toast(e.message)}};
function jsonBackup(){download(JSON.stringify(state,null,2),'Ember-Table-Workspace.json')}
async function restorePortable(f){if(!confirm('Replace the workspace with this backup? Current data will be backed up.'))return;try{await saveQueue;let next;if(f.name.toLowerCase().endsWith('.zip'))next=await api('/api/import',f,'application/zip');else{next=JSON.parse(await f.text());if(!Array.isArray(next.campaigns)||!next.campaigns.every(c=>typeof c.name==='string'))throw Error('Invalid workspace backup');E.normalize(next,uid);await api('/api/workspace',next)}stopAllAudio();state=E.normalize(next,uid);window.__loadFailed=false;undoStack=[];redoStack=[];lastSnapshot=JSON.stringify(state);save();render();toast('Workspace restored')}catch(e){toast(e.message)}}
async function loadBackups(){try{const r=await fetch('/api/backups'),list=await r.json();const el=$('#backupList');if(!el)return;el.innerHTML=list.map(b=>`<div class="row"><span>${esc(new Date(b.time*1000).toLocaleString())}</span>${btn('Restore',`recoverBackup('${b.id}')`)}</div>`).join('')||'<p>Backups appear after your first saved changes.</p>'}catch{toast('Unable to read automatic backups')}}
async function recoverBackup(id){if(!confirm('Restore this automatic backup?'))return;try{await saveQueue;state=E.normalize(await api('/api/recover',{id}),uid);window.__loadFailed=false;stopAllAudio();lastSnapshot=JSON.stringify(state);undoStack=[];redoStack=[];render();toast('Automatic backup restored')}catch(e){toast(e.message)}}
form=function(title,fields,submit){$('#fields').innerHTML=`<h2>${title}</h2>`+fields.map(f=>`<label for="f-${f.key}">${esc(f.label)}</label>${f.type==='textarea'?`<textarea id="f-${f.key}" name="${f.key}">${esc(f.value||'')}</textarea>`:f.options?`<select id="f-${f.key}" name="${f.key}">${f.options.map(o=>`<option ${o===f.value?'selected':''}>${esc(o)}</option>`).join('')}</select>`:`<input id="f-${f.key}" name="${f.key}" type="${f.type||'text'}" value="${esc(f.value??'')}" ${f.required||['name','title'].includes(f.key)?'required':''} ${f.type==='number'?`min="${f.min??0}" max="${f.max??999999}" step="${f.step??1}"`:''}>`}`).join('');$('#form').onsubmit=async e=>{e.preventDefault();try{await submit(Object.fromEntries(new FormData(e.target)));E.normalize(state,uid);save();$('#modal').close();render()}catch(err){toast(err.message||'Please check your entry')}};if(!$('#modal').open)$('#modal').showModal()};
// Saves are serialized; the desktop close handler waits until edits have reached disk.
window.__saving=0;save=function(){if(window.__loadFailed)return;const snapshot=JSON.stringify(state);if(snapshot===lastSnapshot&&window.__saving===0&&!isTimeTravel)return;if(snapshot!==lastSnapshot&&!isTimeTravel){undoStack.push(lastSnapshot);if(undoStack.length>25)undoStack.shift();redoStack=[]}lastSnapshot=snapshot;window.__saving++;setSaveStatus('Saving…');saveQueue=saveQueue.catch(()=>{}).then(()=>api('/api/workspace',JSON.parse(snapshot))).then(()=>{window.__saveError=false;setSaveStatus('Saved locally')}).catch(e=>{window.__saveError=true;setSaveStatus('Save failed · export a backup');toast('Save failed: '+e.message)}).finally(()=>window.__saving--)};
// Persistent tools are available in both roles and survive page navigation.
const controls=document.createElement('div');controls.className='globaltools';controls.innerHTML=`<span id="saveStatus">Saved locally</span>${btn('↶','undo()')}${btn('↷','redo()')}${btn('⬡ Roll dice','openDice()','gold')}`;document.body.append(controls);
document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo()}});
$('#restore').accept='.zip,.json';$('#restore').onchange=e=>{if(e.target.files[0])restorePortable(e.target.files[0])};
const oldGo=go;go=function(p){if(scratchTimer){clearTimeout(scratchTimer);scratchTimer=null;window.__scratchPending=false;save()}oldGo(p)};
if(state._recovery){toast(state._recovery);delete state._recovery}if(window.__loadFailed){page='Backups';toast('Saved data could not load. Restore a backup; existing files have been preserved.')}else{lastSnapshot='';save()}render();
